css:
.d-pw{position:relative;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-pw-main{position:absolute;inset:0;display:flex;align-items:flex-end;padding:10px;background:linear-gradient(160deg,color-mix(in srgb,var(--ink) 74%,var(--paper)),color-mix(in srgb,var(--ink) 48%,var(--paper)))}
.d-pw-main span{font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;color:var(--paper);opacity:.8}
.d-pw-pip{position:absolute;right:10px;bottom:10px;width:96px;height:60px;padding:6px;border:1px solid var(--paper);border-radius:6px;background:color-mix(in srgb,var(--ink) 35%,var(--paper));color:var(--paper);cursor:grab;touch-action:none;transition:left 200ms var(--ease),top 200ms var(--ease),right 200ms var(--ease),bottom 200ms var(--ease)}
.d-pw-pip b{display:block;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;font-weight:400}
.d-pw-pip span{display:block;margin-top:2px;font-size:8px;opacity:.75;line-height:1.4}
.d-pw-pip button{position:absolute;right:2px;top:2px;width:18px;height:18px;border:0;border-radius:2px;background:transparent;color:var(--paper);font-size:10px;cursor:pointer;opacity:.8}

init:
root => {
  var box = root.querySelector('[data-box]');
  var pip = root.querySelector('[data-pip]');
  var back = root.querySelector('[data-back]');
  if (!box || !pip) return;
  var drag = null;
  pip.addEventListener('pointerdown', function (e) {
    if (e.target === back) return;
    var r = pip.getBoundingClientRect(), br = box.getBoundingClientRect();
    drag = { dx: e.clientX - r.left, dy: e.clientY - r.top, w: r.width, h: r.height, bw: br.width, bh: br.height };
    pip.style.transition = 'none';
    pip.setPointerCapture(e.pointerId);
  });
  pip.addEventListener('pointermove', function (e) {
    if (!drag) return;
    var br = box.getBoundingClientRect();
    var x = Math.max(0, Math.min(drag.bw - drag.w, e.clientX - br.left - drag.dx));
    var y = Math.max(0, Math.min(drag.bh - drag.h, e.clientY - br.top - drag.dy));
    pip.style.left = x + 'px'; pip.style.top = y + 'px';
    pip.style.right = 'auto'; pip.style.bottom = 'auto';
  });
  var end = function () {
    if (!drag) return;
    drag = null;
    pip.style.transition = 'left 200ms cubic-bezier(.2,.75,.25,1),top 200ms cubic-bezier(.2,.75,.25,1)';
    var br = box.getBoundingClientRect(), r = pip.getBoundingClientRect();
    var left = (r.left - br.left) < (br.width - r.width) / 2;
    var top = (r.top - br.top) < (br.height - r.height) / 2;
    pip.style.left = left ? '10px' : (br.width - r.width - 10) + 'px';
    pip.style.top = top ? '10px' : (br.height - r.height - 10) + 'px';
  };
  pip.addEventListener('pointerup', end);
  pip.addEventListener('pointercancel', end);
  if (back) back.addEventListener('click', function () { pip.style.transition = 'none'; pip.style.left = ''; pip.style.top = ''; pip.style.right = '10px'; pip.style.bottom = '10px'; });
}
